public void makeWorkflow()
{
    TFMWorkflowsTable wfTable = this.makeEntry(MobConstants::Count());

    wfTable.addStepBlock(classStr(TFMWorkflowBlockDimensions));
    wfTable.addStepBlock(classStr(TFMWorkflowBlockQuantity));

    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'SerialNumber', 'validationWarningType', TFMOverDeliveryValidation::Block);
    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'ToBin', 'validationWarningType', TFMOverDeliveryValidation::Warn);
    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'FromBin', 'validationWarningType', TFMOverDeliveryValidation::Block);
    TFMGenericParms::CreateOrUpdateParameter(TFMWorkflowsTable::GetWorkflowDomainName(wfTable.WorkflowName), 'Quantity', 'minValue', 0);
}
